          0 => 'Napomena: Provedeno vrijeme na suncu povećava rizik pojave raka kože. Za smanjenje rizika koristite proizvod s većim zaštitnim faktorom od SPF 15. Smanjite vrijeme sunčanja posebno u razdoblju između 10 i 16 sati. Obucite košulju dugih rukava, hlače, kapu i sunčane naočale. Za djecu mlađu od 6 mjeseci potražite savjet liječnika.Ne provodite previše vremena na suncu ni u slučaju da koristite zaštitnu kremu. Dojenčad i malenu djecu zaštitite od neposrednog sunčevog zračenja. Izloženost suncu predstavlja opasnost za zdravlje. Upotrebljavajte zaštitnu kremu najmanje svaka 2 sata posebno u slučaju znojenja, nakon kupanja brisanja ručnikom. Za zaštitu tijela prosječne odrasle osobe koristite približno količinu koja odgovara 6 malene žlice (oko 36 g) kreme. Smanjenjem količine značajno se povećava zaštitu od utjecaja sunca. Upozorenje: samo za vanjsku uporabu! Izbjegavajte da krema dođe u dodir s očima. Ako bi se to ipak dogodilo isplahnite oči vodom. Za korištenje kod djece mlađe od 6 mjeseci zatražite mišljen ...Prikaži više',
        ),
