        0 => 'UPUTA ZA UPORABU1. Otvorite vrećicu i odmotajte masku. 2. Maska je zaštićena tkaninom na svakoj strani. Skinite jedan sloj i odbacite. 3. Postavite nezaštićenu stranu maske na lice i lagano pritisnite. 4. Uklonite drugi sloj tkanine i odbacite. 5. Nakon približno 20 minuta skinite masku s lica i bacite. Nema potrebe za ispiranjem lica. Ostatke proizvoda umasirajte u lice i vrat za mladalački izgled.',
