        0 => 'UPUTA ZA UPORABUDoručak: uzmite 3 Forever Therm Plus tablete s 250 ml vode. Sredinom jutra: uzmite 2 Forever DuoPure tablete s 250 ml vode. Uzmite 8 Forever Sensatiable tableta za žvakanje u bilo koje vrijeme tijekom dana s 250 ml vode. Poslijepodne: Pomiješajte 1 mjericu Forever Plant Protein s 250 ml nezaslađenog biljnog mlijeka ili vode. Sredina poslijepodneva: Otopite 1 Forever Multi Fizz šumeću tabletu u 300 ml vode. Također, popijte 330 ml Forever Aloe Vera Gel. Navečer (ili prije spavanja): Pomiješajte 1 mjericu Forever Plant Protein s 250 ml nezaslađenog biljnog mlijeka ili vode. Također, ulijte sadržaj 1 paketića Forever LemonBlast u 250ml hladne vode i dobro promiješajte.',
