      'label_evidence' => 
      array (
        'extractor_version' => 'fcc-label-safety-suffix-v1',
        'usage_text' => 'UPUTA ZA UPORABUDoručak: uzmite 3 Forever Therm Plus tablete s 250 ml vode. Sredinom jutra: uzmite 2 Forever DuoPure tablete s 250 ml vode. Uzmite 8 Forever Sensatiable tableta za žvakanje u bilo koje vrijeme tijekom dana s 250 ml vode. Poslijepodne: Pomiješajte 1 mjericu Forever Plant Protein s 250 ml nezaslađenog biljnog mlijeka ili vode. Sredina poslijepodneva: Otopite 1 Forever Multi Fizz šumeću tabletu u 300 ml vode. Također, popijte 330 ml Forever Aloe Vera Gel. Navečer (ili prije spavanja): Pomiješajte 1 mjericu Forever Plant Protein s 250 ml nezaslađenog biljnog mlijeka ili vode. Također, ulijte sadržaj 1 paketića Forever LemonBlast u 250ml hladne vode i dobro promiješajte.',
        'ingredients_text' => 'Forever Therm Plus: stabilizator (mikrokristalna celuloza), list zelenog čaja (Camellia sinensis) u prahu, ekstrakt sjemenki guarane (Paulinia cupana, sadrži kofein), ekstrakt sjemenki zelene kave (Coffea robusta), tvari protiv zgrudnjavanja (magnezijev karbonat, stearinska kiselina, silicijev dioksid), stabilizator (umrežena celulozna guma), vitamin C (L-askorbinska kiselina), ovojnica tablete (zgušnjivač (natrij karboksimetil celuloza)), dekstrin, dekstroza, trigliceridi srednjeg lanca, regulator kiselosti (trinatrijev citrat), ekstrakt cvijeta nevena šafran (Crocus sativus), niacin (nikotinamid), pantotenska kiselina (kalcijev D-pantotenat), vitamin D (kolekalciferol), riboflavin, tiamin (tiamin hidroklorid), vitamin B12 (cijanokobalamin).Forever DuoPure: sredstvo za povećanje volumena (dikalcijev fosfat), stabilizator (mikrokristalna celuloza), kolin (kolin bitartrat), sredstva protiv zgrudnjavanja (magnezijev oksid, stearinska kiselina, silicijev dioksid), ekstrakt ploda nara (Punica granatum L.), stabilizator (povezana celulozna guma), ovojnica tablete (zgušnjivač (natrijeva karboksimetil celuloza)), dekstrin, dekstroza, trigliceridi srednjeg lanca, regulator kiselosti (trinatrijev citrat), alfa-lipoična kiselina, vitamin B6 (piridoksin hidroklorid), vitamin B12 (cijanokobalamin), folna kiselina (pteroilmonoglutaminska kiselina), ekstrakt korijena japanskog dvorca (Polygonum cuspidatum, sadrži 20% trans-resveratrola). Forever Multi Fizz: regulatori kiselosti (natrij bikarbonat, limunska kiselina, jabučna kiselina, aroma, boja (betanin), vitamin E (D-alfa-tokoferil acetat), trigliceridi srednjeg lanca, sredstvo za povećanje volumena (mikrokristalna celuloza), vitamin C (L-askorbinska kiselina), tvari protiv zgrudnjavanja (silicijev dioksid, stearinska kiselina), zaslađivač (steviol glikozidi iz stevije), stabilizator (umrežena celulozna guma), biotin (D-biotin), pantotenska kiselina (kalcijev D-pantotenat), vitamin B6 (piridoksin) hidroklorid), riboflavin, tiamin (tiamin hidroklorid), vitamin B12 (cijanokobalamin), folna kiselina (pteroilmonoglutaminska kiselina). Forever LemonBlast: kukuruzna vlakna, kukuruzni dekstrin, limunov sok u prahu (Citrus x limun), magnezij (magnezijev karbonat), regulatori kiselosti (jabučna kiselina, limunska kiselina), sredstvo protiv zgrudnjavanja (silicijev dioksid), fruktooligosaharidi, prah korijena kurkume (Curcuma longa), kajenski papar u prahu (Capsicum annuum L.), vitamin C (L-askorbinska kiselina), sladila (sukraloza, steviol glikozidi iz stevije). Forever Sensatiable: zobene mekinje, sladilo: sorbitol, med u prahu, aroma vanilije i limuna, srednje lančani trigliceridi, stabilizatori: mikrokristalna celuloza i umrežena celulozna guma, hidrolizat proteina kvasca (Saccharomyces cerevisiae), zgušnjivač: guar guma, tvar protiv zgrudnjavanja: silicijev dioksid, stabilizator: stearinska kiselina, glukomanan. Forever Plant Protein: Izolat proteina graška (Pisum sativum) (59%), prah proteina bundeve (Cucurbita pepo) (26%), aroma vanilije, maltodekstrin, fruktooligosaharidi, srednjelančani trigliceridi, zgušnjivač: guar guma, aroma, tvar protiv zgrudnjavanja: magnezijeve soli masnih kiselina, sladilo: steviol glikozidi, prah soka lista aloe (Aloa barbadensis). Forever Aloe Vera Gel: stabilizirani Aloe vera gel 99,7% (Aloe barbadensis Mill. – pulpa lista), vitamin C (L-askorbinska kiselina), antioksidans: askorbinska kiselina, regulator kiselosti: limunska kiselina.',
