        0 => 'UPUTA ZA UPORABU1. Logic Aloe Gel CleanserKoristite gel za čišćenje ujutro i navečer kako biste s kože uklonili prljavštinu, masnoću i šminku. Isperite toplom vodom. Slijedite Logic by Forever™ Balancing Aloe Essence i zatim Logic by Forever™ Soothing Gel Moisturizer iz Forevera. 2. Logic Balancing Aloe EssenceKoristite ujutro i navečer nakon Logic by Forever™ Aloe Gel Cleanser za osvježenje, toniranje i uravnoteženje kože. Nanesite vatom na cijelo lice ili ulijte malu količinu u dlanove i nježno utapkajte u kožu. Slijedite Logic by Forever™ umirujuću hidratantnu kremu u gelu. 3. Logic Soothing Gel MoisturizerNanesite ujutro i navečer nakon Logic by Forever™ Balancing Aloe Essence za umirujući osjećaj i poticanje mekog, uravnoteženog tena.',
