        0 => 'Stabilizator (mikrokristalna celuloza), ekstrakt lista zelenog čaja (Camellia sinensis**), ekstrakt sjemenki guarane (Paullinia cupana) [kofein, ekstrakt sjemenki guarane], ekstrakt zrna zelene kave (Coffea robusta), vitamin C (l-askorbinska kiselina ), sredstvo protiv zgrudnjavanja (stearinska kiselina, silicijev dioksid), stabilizator (umrežena celulozna guma), materijal za oblaganje [zgušnjivač (natrij karboksimetilceluloza), dekstrin, dekstroza, trigliceridi srednjeg lanca, regulator kiselosti (trinatrijev citrat)], niacin (nikotinamid), pantotenska kiselina (d-kalcij pantotenat), vitamin B6 (piridoksin hidroklorid), riboflavin, tiamin (tiamin hidroklorid), vitamin B12 (cijanokobalamin), folna kiselina (pteroilmonoglutaminska kiselina).',
