        'expected' => ['source_id' => '26bd0351be8aa57d24c8ce4d', 'source_url' => 'https://foreverliving.com/shop/hrv/hr-hr/products/613-FOREVER-MARINE-COLLAGEN', 'content_sha256' => '7ef17074c27c82afb6ab14bb3a3a3b283a6effc42e4c7fd796b264e98900b77f', 'usage_sha256' => 'ff1e1c960f34ea12919b7774679a2aa1a484f299eb7e19639aa13932bd1e7ab0', 'ingredients_sha256' => '12286c02577ee04299e62747aabdde0a4d4632db7c302da866769c7e86caeb0c'],
        'replace' => ['identity_status' => 'verified_reviewed', 'identity_review_note' => 'Reviewed exact HR item 613 Forever Marine Collagen; one liquid sachet is consumed orally.', 'page_route' => 'oral', 'route_override_review_note' => 'Exact HR item 613 usage instructs one liquid sachet daily; reviewed oral label route overrides the stale mixed legacy grouping.', 'aliases' => ['Forever Marine Collagen']],
    ],
];

$reviewedSourceKeys = [];
foreach($manifest['sources'] as &$sourceRecord) {
    $productKey = (string) ($sourceRecord['product_key'] ?? '');
    if(!isset($reviewedSourceOverrides[$productKey])) {
        continue;
    }
    $override = $reviewedSourceOverrides[$productKey];
    $expected = $override['expected'];
    $actualFingerprint = [
        'source_id' => (string) ($sourceRecord['source_id'] ?? ''),
        'source_url' => (string) ($sourceRecord['source_url'] ?? ''),
        'content_sha256' => (string) ($sourceRecord['content_sha256'] ?? ''),
        'usage_sha256' => (string) ($sourceRecord['label_evidence']['section_sha256']['usage'] ?? ''),
        'ingredients_sha256' => (string) ($sourceRecord['label_evidence']['section_sha256']['ingredients'] ?? ''),
    ];
    if($actualFingerprint !== $expected) {
        throw new RuntimeException('Reviewed FCC source baseline changed: ' . $productKey . '.');
    }
    $sourceRecord = array_replace($sourceRecord, $override['replace'], [
        'review_status' => 'approved',
        'review_scope' => 'identity_and_label_facts',
        'is_primary_for_language' => true,
        'safety_review_status' => 'complete',
        'suitability_flags' => [],
        'suitability_review_status' => 'unknown',
        'claim_review_status' => 'unknown',
        'quarantine_reasons' => [],
    ]);
    $sourceRecord['source_refs'][] = [
        'source_type' => 'official_identity_safety_review',
        'review_schema_version' => 'fcc-official-identity-safety-review-v1',
        'language_code' => 'hr',
        'market_code' => 'hr',
        'source_url' => (string) $sourceRecord['source_url'],
        'accessed_at' => (string) $sourceRecord['accessed_at'],
        'content_sha256' => (string) $sourceRecord['content_sha256'],
        'evidence_sha256' => (string) $sourceRecord['evidence_sha256'],
        'section_sha256' => (array) $sourceRecord['label_evidence']['section_sha256'],
        'reviewed_at' => '2026-08-25T21:30:00+00:00',
    ];
    $reviewedSourceKeys[$productKey] = true;
}
unset($sourceRecord);

$missingReviewedSources = array_diff(array_keys($reviewedSourceOverrides), array_keys($reviewedSourceKeys));
if($missingReviewedSources) {
    throw new RuntimeException('Reviewed FCC source records missing: ' . implode(',', $missingReviewedSources) . '.');
}

/*
 * Reconcile structured allergen metadata after the detector was narrowed to
 * exact fish terms.  Every correction is bound to the immutable source and
 * ingredients-section hashes so a future label refresh fails closed.
 */
$structuredAllergenCorrections = [
    'forever-argi' => [
        'expected' => [
            'source_id' => 'ee9774ead234efcf38b8855f',
            'content_sha256' => '86e2e4ea4b9a65ef7621dff8d606cc2a19ea425efae86b7051101a79f41add1a',
            'ingredients_sha256' => 'c9951cf21c49aa896d74becdb86574a80685edcd360feaa9c8823d9d7f7be0fa',
            'allergens_contains' => ['fish'],
        ],
        'allergens_contains' => [],
    ],
    'forever-dx4' => [
        'expected' => [
            'source_id' => '9cefe671b426490a94619541',
            'content_sha256' => '61caed2671adc064e3bec810e7e0d2e059ef03ed9d0935c315285ab0060b333f',
            'ingredients_sha256' => '88cdb9531faf95b9ecf68c75e9621ec5dc181b2591a50c47ff47169244deaf00',
            'allergens_contains' => ['fish', 'bee_products'],
        ],
        'allergens_contains' => ['bee_products'],
    ],
    'forever-kids' => [
        'expected' => [
            'source_id' => 'abe0ef98c47cc2fe1d9ba736',
            'content_sha256' => '339dc5aa728f3a3dd38ef0d9fbbe3c07faad8f65e546226ea9a2d60eea0ec65a',
            'ingredients_sha256' => '17749975b019be276e8adfe59f153410602388729f75739b0084ba1fc17bd47b',
            'allergens_contains' => ['fish'],
        ],
        'allergens_contains' => [],
    ],
    'forever-therm' => [
        'expected' => [
            'source_id' => '58558a0125494d8ae7d800f6',
            'content_sha256' => '618680af909519c936ef4ad87f5d90b3ec07771eea6ae536ac44596b1500d233',
            'ingredients_sha256' => '2608390bf80d5b69b8eec15b2f6da2d5ff0d283dae9de8a689752bbfb77e07ad',
            'allergens_contains' => ['fish'],
        ],
        'allergens_contains' => [],
    ],
];

$correctedAllergenKeys = [];
foreach($manifest['sources'] as &$sourceRecord) {
    $productKey = (string) ($sourceRecord['product_key'] ?? '');
    if(!isset($structuredAllergenCorrections[$productKey])) {
        continue;
    }
    $correction = $structuredAllergenCorrections[$productKey];
    $actualFingerprint = [
        'source_id' => (string) ($sourceRecord['source_id'] ?? ''),
        'content_sha256' => (string) ($sourceRecord['content_sha256'] ?? ''),
        'ingredients_sha256' => (string) ($sourceRecord['label_evidence']['section_sha256']['ingredients'] ?? ''),
        'allergens_contains' => array_values((array) ($sourceRecord['allergens_contains'] ?? [])),
    ];
    if($actualFingerprint !== $correction['expected']) {
        throw new RuntimeException('Structured allergen correction baseline changed: ' . $productKey . '.');
    }
    $sourceRecord['allergens_contains'] = $correction['allergens_contains'];
    $correctedAllergenKeys[$productKey] = true;
}
unset($sourceRecord);

$missingAllergenCorrections = array_diff(array_keys($structuredAllergenCorrections), array_keys($correctedAllergenKeys));
if($missingAllergenCorrections) {
    throw new RuntimeException('Structured allergen correction sources missing: ' . implode(',', $missingAllergenCorrections) . '.');
}

return $manifest;
